// ParseMessagingRpcIds converts a comma-separated string to a slice of MessagingRpcId enum values
// Returns an error if any value is invalid
func ParseMessagingRpcIds(s string) ([]MessagingRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]MessagingRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseMessagingRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

