// ParseGatewayStateServiceRpcIds converts a comma-separated string to a slice of GatewayStateServiceRpcId enum values
// Returns an error if any value is invalid
func ParseGatewayStateServiceRpcIds(s string) ([]GatewayStateServiceRpcId, error) {
	if s == "" {
		return nil, nil
	}
	parts := strings.Split(s, ",")
	result := make([]GatewayStateServiceRpcId, 0, len(parts))
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed == "" {
			continue
		}
		val, err := ParseGatewayStateServiceRpcId(trimmed)
		if err != nil {
			return nil, err
		}
		result = append(result, val)
	}
	return result, nil
}

