// ConfigToEnvVar converts Config to environment variable key-value pairs.
func ConfigToEnvVar(v *Config) map[string]string {
	if v == nil {
		return nil
	}
	result := make(map[string]string)
	result["PROTO_SERVICES_MSGGATEWAY_CONFIG_PROVIDER"] = ProviderToString(v.Provider)
	result["PROTO_SERVICES_MSGGATEWAY_CONFIG_BOT_TOKEN"] = v.BotToken
	result["PROTO_SERVICES_MSGGATEWAY_CONFIG_APP_TOKEN"] = v.AppToken
	if v.ApiEndpoint != nil {
		for k, val := range host.HostToEnvVar(v.ApiEndpoint) {
			result[k] = val
		}
	}
	result["PROTO_SERVICES_MSGGATEWAY_CONFIG_WORKSPACE_ID"] = v.WorkspaceId
	result["PROTO_SERVICES_MSGGATEWAY_CONFIG_RECONNECT_DELAY_SECONDS"] = strconv.FormatInt(int64(v.ReconnectDelaySeconds), 10)
	result["PROTO_SERVICES_MSGGATEWAY_CONFIG_MAX_MESSAGE_LENGTH"] = strconv.FormatInt(int64(v.MaxMessageLength), 10)
	result["PROTO_SERVICES_MSGGATEWAY_CONFIG_TRACE_ID"] = v.TraceId
	result["PROTO_SERVICES_MSGGATEWAY_CONFIG_NOOP"] = strconv.FormatBool(v.Noop)
	return result
}

// ConfigFromEnvVar creates Config from environment variable key-value pairs.
func ConfigFromEnvVar(env map[string]string) (*Config, error) {
	result := &Config{}
	if val, ok := env["PROTO_SERVICES_MSGGATEWAY_CONFIG_PROVIDER"]; ok && val != "" {
		parsed, err := ParseProvider(val)
		if err != nil {
			return nil, err
		}
		result.Provider = parsed
	}
	if val, ok := env["PROTO_SERVICES_MSGGATEWAY_CONFIG_BOT_TOKEN"]; ok && val != "" {
		result.BotToken = val
	}
	if val, ok := env["PROTO_SERVICES_MSGGATEWAY_CONFIG_APP_TOKEN"]; ok && val != "" {
		result.AppToken = val
	}
	if sub, err := host.HostFromEnvVar(env); err != nil {
		return nil, err
	} else if sub != nil {
		result.ApiEndpoint = sub
	}
	if val, ok := env["PROTO_SERVICES_MSGGATEWAY_CONFIG_WORKSPACE_ID"]; ok && val != "" {
		result.WorkspaceId = val
	}
	if val, ok := env["PROTO_SERVICES_MSGGATEWAY_CONFIG_RECONNECT_DELAY_SECONDS"]; ok && val != "" {
		parsed, err := strconv.ParseInt(val, 10, 32)
		if err != nil {
			return nil, err
		}
		result.ReconnectDelaySeconds = int32(parsed)
	}
	if val, ok := env["PROTO_SERVICES_MSGGATEWAY_CONFIG_MAX_MESSAGE_LENGTH"]; ok && val != "" {
		parsed, err := strconv.ParseInt(val, 10, 32)
		if err != nil {
			return nil, err
		}
		result.MaxMessageLength = int32(parsed)
	}
	if val, ok := env["PROTO_SERVICES_MSGGATEWAY_CONFIG_TRACE_ID"]; ok && val != "" {
		result.TraceId = val
	}
	if val, ok := env["PROTO_SERVICES_MSGGATEWAY_CONFIG_NOOP"]; ok && val != "" {
		parsed, err := strconv.ParseBool(val)
		if err != nil {
			return nil, err
		}
		result.Noop = parsed
	}
	return result, nil
}

